def decompress(src, size=None):
    pos = 0; bits = 0; nb = 0
    def getbits(n):
        nonlocal pos, bits, nb
        while nb < n:
            bits |= (src[pos] if pos < len(src) else 0) << nb; pos += 1; nb += 8
        v = bits & ((1 << n) - 1); bits >>= n; nb -= n; return v
    def lookup(tree):
        node = tree[0]
        while not isinstance(node, int):
            node = tree[node[1] if getbits(1) else node[0]]
        return -node - 1
    mode, dtype = getbits(8), getbits(8)
    assert mode in (0, 1) and dtype in (4, 5, 6), (mode, dtype)
    out = bytearray()
    while size is None or len(out) < size:
        if getbits(1):
            v = lookup(LENGTH_TREE)
            ln = v + 2 if v < 8 else 8 + (1 << (v - 7)) + getbits(v - 7)
            if ln == 519: break
            v = lookup(DISTANCE_TREE)
            off = ((v << 2) | getbits(2)) if ln == 2 else ((v << dtype) | getbits(dtype))
            off += 1
            for _ in range(ln): out.append(out[-off])
        else:
            out.append(lookup(ASCII_TREE) if mode == 1 else getbits(8))
    return bytes(out)
